insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('biodiversidad-cerca-de-ti-que-especies-viven-en-un-parque-o-area','ambiente',array['ciencias','ciudades']::text[],'Biodiversidad cerca de ti: ¿qué especies viven en un parque o área verde?','Observa y registra las plantas, aves e insectos de un parque o área verde cercana para armar un inventario con fotos y descubrir cuánta vida hay donde casi nadie mira.','Investigación','~25 h',25,array['Biodiversidad','Observación']::text[],array['investigar']::text[],'propios',NULL,'biologia ingenieria ambiental geografia educacion ingenieria forestal estadistica diseno grafico ciencia de datos observacion de campo. identificacion de especies. organizacion de datos. comunicacion visual. guias de campo o una aplicacion de identificacion. camara o celular. hoja de calculo.',$a31sld${"id": "biodiversidad-cerca-de-ti-que-especies-viven-en-un-parque-o-area", "area": "ambiente", "areas2": ["ciencias", "ciudades"], "titulo": "Biodiversidad cerca de ti: ¿qué especies viven en un parque o área verde?", "resumen": "Observa y registra las plantas, aves e insectos de un parque o área verde cercana para armar un inventario con fotos y descubrir cuánta vida hay donde casi nadie mira.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Biodiversidad", "Observación"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Biología", "Ingeniería Ambiental", "Geografía", "Educación", "Ingeniería Forestal", "Estadística", "Diseño Gráfico", "Ciencia de Datos"], "problema": ["Los parques y áreas verdes de la ciudad albergan más especies de las que se notan: aves, insectos, árboles, arbustos y hierbas que casi nadie registra. Se pasa por ellos sin mirarlos, y por eso su valor ambiental se subestima.", "Sin un inventario es imposible saber qué hay, qué ha cambiado o qué conviene proteger. Y un registro hecho con orden puede servir a otras personas."], "desarrollar": ["Elige un parque o área verde, define un recorrido y visítalo en varios días y horarios, registrando con fotos y notas las especies que veas, el lugar y la fecha. Identifícalas con guías de campo o aplicaciones de reconocimiento y anota cuáles no pudiste identificar.", "Organiza el inventario en una tabla o catálogo, muestra qué grupos son más abundantes y comenta qué especies parecen nativas y cuáles introducidas, con las dudas que queden."], "ampliaciones": [{"titulo": "Comparar dos lugares", "aporta": "compara la diversidad entre dos áreas con características distintas."}, {"titulo": "Diferencias por hora", "aporta": "descubre cómo cambia lo que ves según la hora del día."}, {"titulo": "Catálogo visual", "aporta": "convierte el inventario en un catálogo ilustrado para la comunidad."}], "objetivos": ["Diseñar un recorrido de observación.", "Registrar especies con método.", "Identificar usando fuentes confiables.", "Organizar y presentar los resultados."], "habilidades": ["Observación de campo.", "Identificación de especies.", "Organización de datos.", "Comunicación visual."], "herramientas": ["Guías de campo o una aplicación de identificación.", "Cámara o celular.", "Hoja de cálculo."], "lineamientos": ["Observa sin molestar ni recolectar: no toques nidos, no atrapes animales ni arranques plantas, y respeta las normas del lugar.", "Si no logras identificar una especie, anótala como no identificada en lugar de asignarle un nombre."], "otroSector": "El mismo método de inventario sirve para registrar edificios, comercios, árboles de una calle, especies de un mercado o patrimonio de un barrio."}$a31sld$::jsonb,39),
('guia-para-reconocer-y-proteger-las-especies-nativas-de-tu-zona','ambiente',array['educacion','arte']::text[],'Guía para reconocer y proteger las especies nativas de tu zona','Elabora una guía ilustrada de plantas y animales nativos de tu localidad, con cómo reconocerlos, por qué importan y cómo cuidarlos.','Guía','~25 h',25,array['Especies nativas','Guía']::text[],array['crear','investigar']::text[],'publicos',NULL,'biologia ingenieria ambiental educacion diseno grafico geografia comunicaciones ingenieria forestal antropologia investigacion de fuentes. sintesis de informacion. diseno de informacion. divulgacion cientifica. bases de datos y guias de especies de tu region. un editor de diseno. hoja de calculo.',$a32sld${"id": "guia-para-reconocer-y-proteger-las-especies-nativas-de-tu-zona", "area": "ambiente", "areas2": ["educacion", "arte"], "titulo": "Guía para reconocer y proteger las especies nativas de tu zona", "resumen": "Elabora una guía ilustrada de plantas y animales nativos de tu localidad, con cómo reconocerlos, por qué importan y cómo cuidarlos.", "tipo": "Guía", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Especies nativas", "Guía"], "intencion": ["crear", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Biología", "Ingeniería Ambiental", "Educación", "Diseño Gráfico", "Geografía", "Comunicaciones", "Ingeniería Forestal", "Antropología"], "problema": ["En muchas ciudades se conocen mejor las plantas de jardín o las mascotas que las especies que vivían allí antes. Las especies nativas se pierden en silencio, porque pocos saben identificarlas.", "Una guía local hace que la gente las reconozca y entienda por qué merecen cuidado, algo que los libros generales no ofrecen."], "desarrollar": ["Con fuentes públicas de instituciones científicas y de áreas naturales, elige entre ocho y doce especies nativas de tu zona de distintos grupos, y reúne de cada una cómo reconocerla, dónde vive, qué cuidados necesita su hábitat y qué la amenaza.", "Diseña la guía con una ficha por especie, ilustraciones o fotos con permiso, y pruébala con alguien que no sea de tu carrera para saber si logra identificar lo que dice."], "ampliaciones": [{"titulo": "Guía para niños", "aporta": "crea una versión más simple y juguetona para escolares."}, {"titulo": "Mapa de dónde verlas", "aporta": "marca los lugares públicos donde pueden observarse."}, {"titulo": "Versión digital", "aporta": "convierte la guía en una página con búsqueda por tipo de especie."}], "objetivos": ["Seleccionar especies nativas con criterios claros.", "Reunir información de fuentes confiables.", "Diseñar fichas claras.", "Probar la guía con lectores."], "habilidades": ["Investigación de fuentes.", "Síntesis de información.", "Diseño de información.", "Divulgación científica."], "herramientas": ["Bases de datos y guías de especies de tu región.", "Un editor de diseño.", "Hoja de cálculo."], "lineamientos": ["Usa solo imágenes con permiso o de uso libre y cita cada fuente de información; distingue especies nativas de introducidas.", "No indiques lugares exactos donde viven especies amenazadas, para evitar que sean perturbadas."], "otroSector": "El mismo formato sirve para guías de oficios, de gastronomía local, de patrimonio de un barrio o de plantas medicinales con respaldo científico."}$a32sld$::jsonb,40),
('como-cambian-las-aves-y-los-insectos-segun-la-vegetacion','ambiente',array['ciencias','ciudades']::text[],'¿Cómo cambian las aves y los insectos según la vegetación?','Compara cuántas aves, abejas, mariposas y otros insectos aparecen en lugares con distinta vegetación, como césped, arbustos, árboles o flores, para entender por qué.','Análisis','~25 h',25,array['Biodiversidad','Vegetación']::text[],array['investigar']::text[],'propios',NULL,'biologia ingenieria ambiental estadistica geografia ingenieria forestal educacion ciencia de datos arquitectura diseno de observaciones. analisis estadistico basico. interpretacion de datos ecologicos. comunicacion de resultados. cuaderno de campo o un formulario. cronometro. hoja de calculo.',$a33sld${"id": "como-cambian-las-aves-y-los-insectos-segun-la-vegetacion", "area": "ambiente", "areas2": ["ciencias", "ciudades"], "titulo": "¿Cómo cambian las aves y los insectos según la vegetación?", "resumen": "Compara cuántas aves, abejas, mariposas y otros insectos aparecen en lugares con distinta vegetación, como césped, arbustos, árboles o flores, para entender por qué.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Biodiversidad", "Vegetación"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Biología", "Ingeniería Ambiental", "Estadística", "Geografía", "Ingeniería Forestal", "Educación", "Ciencia de Datos", "Arquitectura"], "problema": ["No todos los espacios verdes sirven igual a la vida silvestre: un césped corto y uniforme alberga menos aves e insectos que un lugar con arbustos, flores y árboles de distintas alturas. Pero se suele diseñar pensando solo en cómo se ve.", "Medir esa diferencia con observaciones ordenadas ayuda a decidir qué tipo de vegetación conviene sembrar para que un espacio sea más rico en vida."], "desarrollar": ["Elige tres o cuatro lugares cercanos con vegetación distinta y observa cada uno el mismo tiempo, a la misma hora y varios días, contando cuántas aves, polinizadores y otros insectos ves, sin atraparlos.", "Compara los resultados con gráficos, relaciona las diferencias con las características de cada lugar y concluye qué tipo de vegetación parece favorecer más la presencia de vida."], "ampliaciones": [{"titulo": "Polinizadores en detalle", "aporta": "enfócate en abejas, mariposas y moscas florícolas y en qué flores visitan."}, {"titulo": "Temporada", "aporta": "repite la observación en otra época y compara."}, {"titulo": "Recomendar plantas", "aporta": "propón qué plantas añadirías a un espacio pobre en vida."}], "objetivos": ["Diseñar observaciones comparables.", "Contar y registrar con constancia.", "Relacionar presencia de especies con vegetación.", "Presentar conclusiones con cautela."], "habilidades": ["Diseño de observaciones.", "Análisis estadístico básico.", "Interpretación de datos ecológicos.", "Comunicación de resultados."], "herramientas": ["Cuaderno de campo o un formulario.", "Cronómetro.", "Hoja de cálculo."], "lineamientos": ["Observa sin perturbar: no atrapes insectos, no te acerques a nidos y evita mover plantas; respeta las normas del lugar.", "Presenta tus resultados como observaciones limitadas a unos días y lugares, no como conclusiones científicas generales."], "otroSector": "El mismo diseño de comparación sirve para estudiar la afluencia de clientes en zonas de un mercado o el uso de espacios públicos según su diseño."}$a33sld$::jsonb,41),
('como-afectan-las-especies-invasoras-a-los-ecosistemas-locales','ambiente',array['ciencias','agricultura']::text[],'¿Cómo afectan las especies invasoras a los ecosistemas locales?','Investiga qué especies introducidas han causado problemas en ecosistemas de tu país, cómo llegaron y qué se hace para controlarlas.','Investigación','~25 h',25,array['Especies invasoras','Ecosistemas']::text[],array['investigar']::text[],'publicos',NULL,'biologia ingenieria ambiental ingenieria agroindustrial geografia estadistica educacion derecho comunicaciones investigacion de fuentes. analisis comparativo. sintesis de informacion. divulgacion cientifica. informes de instituciones cientificas y ambientales. hoja de calculo. un editor de infografias.',$a34sld${"id": "como-afectan-las-especies-invasoras-a-los-ecosistemas-locales", "area": "ambiente", "areas2": ["ciencias", "agricultura"], "titulo": "¿Cómo afectan las especies invasoras a los ecosistemas locales?", "resumen": "Investiga qué especies introducidas han causado problemas en ecosistemas de tu país, cómo llegaron y qué se hace para controlarlas.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Especies invasoras", "Ecosistemas"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Biología", "Ingeniería Ambiental", "Ingeniería Agroindustrial", "Geografía", "Estadística", "Educación", "Derecho", "Comunicaciones"], "problema": ["Algunas plantas y animales introducidos por accidente o con buena intención se multiplican sin control y desplazan a las especies nativas. Los daños no siempre se notan de inmediato, pero pueden afectar cultivos, ríos y bosques.", "Como la mayoría de la gente solo ve una planta o un animal más, rara vez se entiende que alguna de ellas pueda ser un problema."], "desarrollar": ["Con fuentes públicas de instituciones científicas y de áreas protegidas, elige tres especies invasoras presentes en tu país y reúne de cada una cómo llegó, qué daños causa, dónde está y qué medidas se han tomado.", "Prepara un resumen comparativo y una infografía que explique al público cómo reconocer el problema, sin proponer acciones peligrosas."], "ampliaciones": [{"titulo": "Cómo llegan", "aporta": "analiza por qué rutas llegan las especies, como comercio, mascotas o jardinería."}, {"titulo": "Marco legal", "aporta": "revisa qué normas regulan su introducción y control."}, {"titulo": "Divulgación", "aporta": "crea un mensaje breve para quienes tienen jardines o mascotas."}], "objetivos": ["Reunir información de fuentes confiables.", "Comparar casos con criterios claros.", "Entender causas y efectos.", "Comunicar con precisión."], "habilidades": ["Investigación de fuentes.", "Análisis comparativo.", "Síntesis de información.", "Divulgación científica."], "herramientas": ["Informes de instituciones científicas y ambientales.", "Hoja de cálculo.", "Un editor de infografías."], "lineamientos": ["Cita las fuentes y no propongas eliminar ni manipular animales o plantas por tu cuenta: el control debe estar a cargo de autoridades y especialistas.", "No difundas ubicaciones exactas de poblaciones sensibles ni fomentes la liberación de especies."], "otroSector": "El mismo enfoque sirve para estudiar cómo una tecnología, un competidor o una plaga desplaza a lo que ya existía en un mercado o un sistema."}$a34sld$::jsonb,42),
('recuperar-un-espacio-degradado-que-plantas-nativas-elegir','ambiente',array['ciudades','agricultura']::text[],'Recuperar un espacio degradado: ¿qué plantas nativas elegir?','Diseña un plan para recuperar un lote, un talud o un espacio abandonado con plantas nativas, considerando suelo, agua, sol y quién se encargaría del cuidado.','Plan','~25 h',25,array['Restauración','Plantas nativas']::text[],array['resolver','crear']::text[],'ficticios',NULL,'ingenieria ambiental arquitectura biologia ingenieria forestal geografia ingenieria civil diseno grafico administracion diagnostico de espacios. diseno de planes de restauracion. presupuestos basicos. comunicacion visual. guias de plantas nativas de tu region. un croquis o un editor de planos. hoja de calculo.',$a35sld${"id": "recuperar-un-espacio-degradado-que-plantas-nativas-elegir", "area": "ambiente", "areas2": ["ciudades", "agricultura"], "titulo": "Recuperar un espacio degradado: ¿qué plantas nativas elegir?", "resumen": "Diseña un plan para recuperar un lote, un talud o un espacio abandonado con plantas nativas, considerando suelo, agua, sol y quién se encargaría del cuidado.", "tipo": "Plan", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Restauración", "Plantas nativas"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Ingeniería Ambiental", "Arquitectura", "Biología", "Ingeniería Forestal", "Geografía", "Ingeniería Civil", "Diseño Gráfico", "Administración"], "problema": ["Hay terrenos baldíos, bordes de carretera o rincones de un campus cubiertos de basura o de suelo desnudo. Recuperarlos con vegetación mejora el aire, la sombra y la vida silvestre, pero sembrar al azar suele fracasar.", "Las plantas deben elegirse según el lugar y su disponibilidad de agua y sol, y alguien debe cuidarlas después. Sin ese plan, se pierde el esfuerzo."], "desarrollar": ["Elige un espacio degradado, real o inventado, describe su suelo, su sol, su agua disponible y su uso, y con fuentes públicas selecciona entre cinco y ocho especies nativas adecuadas.", "Presenta un plan con un croquis de la siembra, el calendario de cuidados, los materiales, el costo aproximado y quién se encargaría de mantenerlo."], "ampliaciones": [{"titulo": "Presupuesto", "aporta": "calcula cuánto costaría recuperar el espacio y cómo conseguir los recursos."}, {"titulo": "Seguimiento", "aporta": "define qué se mediría cada mes para saber si funciona."}, {"titulo": "Con la comunidad", "aporta": "diseña una jornada de siembra con vecinos o estudiantes."}], "objetivos": ["Describir las condiciones del espacio.", "Elegir plantas adecuadas con criterios claros.", "Diseñar la siembra y el cuidado.", "Estimar costos y responsables."], "habilidades": ["Diagnóstico de espacios.", "Diseño de planes de restauración.", "Presupuestos básicos.", "Comunicación visual."], "herramientas": ["Guías de plantas nativas de tu región.", "Un croquis o un editor de planos.", "Hoja de cálculo."], "lineamientos": ["Si trabajas en un espacio real, pide permiso a quien lo administra antes de intervenirlo y no siembres especies que no sean nativas.", "No uses terrenos peligrosos, con residuos tóxicos o de pendientes inseguras para actividades de siembra."], "otroSector": "El mismo plan sirve para recuperar un local abandonado, rehabilitar una línea de producción o revitalizar un espacio público."}$a35sld$::jsonb,43),
('disena-un-jardin-para-polinizadores','ambiente',array['agricultura','arte']::text[],'Diseña un jardín para polinizadores','Diseña un pequeño jardín, de macetas o de un rincón, pensado para atraer abejas, mariposas y colibríes con plantas de flor adecuadas a tu clima.','Prototipo','~20 h',20,array['Polinizadores','Diseño']::text[],array['crear','resolver']::text[],'ficticios',NULL,'biologia arquitectura ingenieria ambiental diseno grafico ingenieria agroindustrial educacion ingenieria forestal comunicaciones diseno de espacios. seleccion de plantas. planificacion. comunicacion visual. guias de plantas meliferas y de jardineria. un editor de planos o de diagramas. hoja de calculo.',$a36sld${"id": "disena-un-jardin-para-polinizadores", "area": "ambiente", "areas2": ["agricultura", "arte"], "titulo": "Diseña un jardín para polinizadores", "resumen": "Diseña un pequeño jardín, de macetas o de un rincón, pensado para atraer abejas, mariposas y colibríes con plantas de flor adecuadas a tu clima.", "tipo": "Prototipo", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Polinizadores", "Diseño"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Biología", "Arquitectura", "Ingeniería Ambiental", "Diseño Gráfico", "Ingeniería Agroindustrial", "Educación", "Ingeniería Forestal", "Comunicaciones"], "problema": ["Las abejas, las mariposas y otros polinizadores participan en la producción de muchos alimentos, pero su presencia disminuye cuando falta alimento y refugio. Muchos jardines urbanos tienen flores que casi no les sirven.", "Un jardín bien pensado ofrece flores en distintas épocas, refugio y agua, y se puede lograr incluso con pocas macetas."], "desarrollar": ["Define un espacio disponible, real o inventado, y con fuentes públicas elige plantas de flor nativas o adaptadas a tu clima que florezcan en distintas épocas, para que haya alimento durante todo el año.", "Presenta el diseño en un plano sencillo con la distribución, un calendario de floración, una lista de materiales y un cronograma de cuidados."], "ampliaciones": [{"titulo": "Versión en macetas", "aporta": "adapta el diseño a un balcón o a una azotea."}, {"titulo": "Registro de visitas", "aporta": "propón cómo contar qué polinizadores llegan y cuándo."}, {"titulo": "Cartel educativo", "aporta": "crea un cartel que explique al público por qué importan los polinizadores."}], "objetivos": ["Elegir plantas adecuadas a un clima y un espacio.", "Planificar la floración durante el año.", "Diseñar la distribución.", "Plantear cómo evaluar el resultado."], "habilidades": ["Diseño de espacios.", "Selección de plantas.", "Planificación.", "Comunicación visual."], "herramientas": ["Guías de plantas melíferas y de jardinería.", "Un editor de planos o de diagramas.", "Hoja de cálculo."], "lineamientos": ["Usa plantas y semillas de fuentes confiables y evita especies invasoras; no uses pesticidas en un jardín para polinizadores.", "Si lo construyes de verdad, ten cuidado con personas alérgicas a las picaduras y ubica el jardín lejos de zonas de mucho tránsito."], "otroSector": "La misma idea de diseñar para un usuario no humano sirve para espacios para mascotas, aves urbanas o fauna silvestre."}$a36sld$::jsonb,44),
('que-transporte-deja-menos-huella-en-tu-recorrido-habitual','ambiente',array['ciudades']::text[],'¿Qué transporte deja menos huella en tu recorrido habitual?','Compara la huella de carbono, el tiempo y el costo de las formas de hacer un mismo recorrido, como caminar, bus, tren, bicicleta o auto compartido, y descubre cuál conviene.','Análisis','~18 h',18,array['Transporte','Huella de carbono']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental ingenieria civil ingenieria industrial geografia estadistica economia administracion ciencia de datos recoleccion de datos. calculo con factores de emision. analisis comparativo. comunicacion de resultados. hoja de calculo. factores de emision publicados. mapas con tiempos de viaje.',$a37sld${"id": "que-transporte-deja-menos-huella-en-tu-recorrido-habitual", "area": "ambiente", "areas2": ["ciudades"], "titulo": "¿Qué transporte deja menos huella en tu recorrido habitual?", "resumen": "Compara la huella de carbono, el tiempo y el costo de las formas de hacer un mismo recorrido, como caminar, bus, tren, bicicleta o auto compartido, y descubre cuál conviene.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Transporte", "Huella de carbono"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Civil", "Ingeniería Industrial", "Geografía", "Estadística", "Economía", "Administración", "Ciencia de Datos"], "problema": ["Elegir cómo moverse suele depender del tiempo, el costo o la costumbre, y casi nunca de la huella ambiental. Pero las diferencias entre un auto individual, un bus lleno o una caminata son grandes y casi nadie las conoce.", "Además, no todas las personas pueden elegir cualquier medio: depende de lo que existe en su zona. Un análisis útil considera esa realidad."], "desarrollar": ["Elige un recorrido real que hagas con frecuencia o uno típico de tu ciudad, define las opciones disponibles y registra distancia, tiempo y costo de cada una. Busca factores de emisión públicos para cada medio y calcula la huella por viaje.", "Presenta una tabla comparativa con huella, tiempo y costo, indica cuál conviene según el criterio y explica qué limita a las personas para cambiar de opción."], "ampliaciones": [{"titulo": "Otros recorridos", "aporta": "repite con un trayecto más largo, como una ida a otra ciudad."}, {"titulo": "Ocupación", "aporta": "estima cómo cambia la huella según qué tan lleno vaya el vehículo."}, {"titulo": "Costo total", "aporta": "incluye costos ocultos como estacionamiento, mantenimiento o seguro."}], "objetivos": ["Definir un recorrido comparable.", "Reunir datos de tiempo, costo y emisiones.", "Comparar con criterios claros.", "Reconocer las limitaciones de cada opción."], "habilidades": ["Recolección de datos.", "Cálculo con factores de emisión.", "Análisis comparativo.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Factores de emisión publicados.", "Mapas con tiempos de viaje."], "lineamientos": ["Cita los factores de emisión y aclara que son promedios: la huella real varía según el vehículo y la ocupación.", "No plantees que todos puedan cambiar de medio: considera seguridad, accesibilidad y disponibilidad real del servicio."], "otroSector": "La misma comparación sirve para evaluar opciones de logística, de envío de productos o de viajes de trabajo."}$a37sld$::jsonb,45),
('una-semana-de-movilidad-sostenible','ambiente',array['ciudades','salud']::text[],'Una semana de movilidad sostenible','Cambia durante una semana algunos de tus traslados por alternativas más sostenibles y anota cuánto cambió tu huella, tu tiempo y tu comodidad.','Plan','~15 h',15,array['Movilidad','Reto']::text[],array['resolver','crear']::text[],'propios',NULL,'ingenieria ambiental ingenieria civil psicologia geografia estadistica educacion comunicaciones administracion planificacion. registro de datos. analisis comparativo. reflexion critica. hoja de calculo o cuaderno. una aplicacion de mapas. factores de emision publicados.',$a38sld${"id": "una-semana-de-movilidad-sostenible", "area": "ambiente", "areas2": ["ciudades", "salud"], "titulo": "Una semana de movilidad sostenible", "resumen": "Cambia durante una semana algunos de tus traslados por alternativas más sostenibles y anota cuánto cambió tu huella, tu tiempo y tu comodidad.", "tipo": "Plan", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Movilidad", "Reto"], "intencion": ["resolver", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Civil", "Psicología", "Geografía", "Estadística", "Educación", "Comunicaciones", "Administración"], "problema": ["Se dice que conviene usar más el transporte público, caminar o ir en bicicleta, pero pocas personas lo prueban de forma ordenada. Entre lo que se supone y lo que se vive hay una distancia, hecha de tiempos, costos y seguridad.", "Probar con un plan concreto permite saber qué cambios son realistas para ti y qué obstáculos aparecen."], "desarrollar": ["Registra una semana normal de traslados, elige los que podrías cambiar, como acortar un viaje en auto, combinar rutas o caminar un tramo, y planifica una semana de prueba con alternativas viables y seguras.", "Durante la semana anota tiempo, costo, comodidad y percepción de seguridad en cada traslado, calcula el cambio en huella y presenta un balance con lo que mantendrías."], "ampliaciones": [{"titulo": "En grupo", "aporta": "invita a un grupo pequeño y compara experiencias."}, {"titulo": "Mapa de obstáculos", "aporta": "marca los puntos del recorrido donde fue más difícil o inseguro."}, {"titulo": "Propuesta a la ciudad", "aporta": "propón dos cambios que facilitarían moverse así a más personas."}], "objetivos": ["Registrar la línea base de traslados.", "Elegir cambios seguros y realistas.", "Comparar antes y después.", "Reflexionar sobre los obstáculos."], "habilidades": ["Planificación.", "Registro de datos.", "Análisis comparativo.", "Reflexión crítica."], "herramientas": ["Hoja de cálculo o cuaderno.", "Una aplicación de mapas.", "Factores de emisión publicados."], "lineamientos": ["Prioriza tu seguridad: evita rutas peligrosas, de noche o poco transitadas, y no uses medios que no sean seguros para ti.", "Presenta los resultados como una experiencia personal, sin juzgar a quienes no pueden cambiar de medio."], "otroSector": "La misma estructura de prueba sirve para ensayar cambios de horario de trabajo, de rutinas de estudio o de formas de comunicarse."}$a38sld$::jsonb,46),
('fuentes-de-contaminacion-de-tu-entorno-cercano-aire-humo-y-resid','ambiente',array['ciudades','salud']::text[],'Fuentes de contaminación de tu entorno cercano: aire, humo y residuos','Recorre tu barrio e identifica qué puede estar contaminando, como humo, quemas, basura acumulada o tránsito intenso, para armar un mapa de fuentes y proponer mejoras.','Análisis','~22 h',22,array['Contaminación','Mapas']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental geografia ingenieria civil quimica estadistica sociologia ingenieria industrial arquitectura observacion de campo. mapeo. clasificacion. redaccion de reportes. un mapa digital. camara o celular. hoja de calculo.',$a39sld${"id": "fuentes-de-contaminacion-de-tu-entorno-cercano-aire-humo-y-resid", "area": "ambiente", "areas2": ["ciudades", "salud"], "titulo": "Fuentes de contaminación de tu entorno cercano: aire, humo y residuos", "resumen": "Recorre tu barrio e identifica qué puede estar contaminando, como humo, quemas, basura acumulada o tránsito intenso, para armar un mapa de fuentes y proponer mejoras.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Contaminación", "Mapas"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Geografía", "Ingeniería Civil", "Química", "Estadística", "Sociología", "Ingeniería Industrial", "Arquitectura"], "problema": ["La contaminación no siempre viene de grandes fábricas: también aparece en quemas de residuos, basura acumulada en esquinas, tránsito congestionado o talleres sin control. Muchas de esas fuentes están a la vista, pero no se registran.", "Sin un registro, es difícil explicar un problema a las autoridades o a los vecinos, y casi imposible saber por dónde empezar."], "desarrollar": ["Recorre una zona definida, identifica y registra con fotos de espacios sin personas posibles fuentes de contaminación, como humo, olores, residuos o tránsito, y anota su ubicación, horario y cómo te afectan al pasar por ahí.", "Ubícalas en un mapa, clasifícalas por tipo y por qué tan frecuentes parecen, y propón qué instancia podría atenderlas y qué cambios simples ayudarían."], "ampliaciones": [{"titulo": "Repetir en otro horario", "aporta": "compara lo que cambia entre mañana, tarde y noche."}, {"titulo": "Datos públicos", "aporta": "compara tus observaciones con los datos de una estación de monitoreo cercana."}, {"titulo": "Reporte para la autoridad", "aporta": "prepara un reporte claro para presentarlo a una municipalidad."}], "objetivos": ["Diseñar un recorrido y criterios de registro.", "Documentar fuentes con orden.", "Representarlas en un mapa.", "Plantear acciones y a quién corresponden."], "habilidades": ["Observación de campo.", "Mapeo.", "Clasificación.", "Redacción de reportes."], "herramientas": ["Un mapa digital.", "Cámara o celular.", "Hoja de cálculo."], "lineamientos": ["Recorre solo espacios públicos y acompañado, evita zonas peligrosas y no te acerques a quemas o a lugares con humo intenso.", "No fotografíes a personas, placas ni viviendas, ni acuses a nadie de causar la contaminación: describe lo observado."], "otroSector": "El mismo mapeo sirve para registrar ruido, luminarias dañadas, veredas rotas, espacios sin accesibilidad u otros problemas de un barrio."}$a39sld$::jsonb,47),
('disena-una-campana-de-accion-ambiental','ambiente',array['arte','sociedad']::text[],'Diseña una campaña de acción ambiental','Diseña una campaña con un objetivo claro, un público concreto, mensajes probados y una forma de medir si logró algo, sobre un tema ambiental que te importe.','Plan','~25 h',25,array['Campaña','Comunicación']::text[],array['crear','resolver']::text[],'ficticios',NULL,'comunicaciones publicidad diseno grafico ingenieria ambiental psicologia educacion sociologia administracion comunicacion persuasiva. diseno grafico basico. pruebas con usuarios. planificacion de campanas. un editor de diseno o de presentaciones. un formulario anonimo. hoja de calculo.',$a40sld${"id": "disena-una-campana-de-accion-ambiental", "area": "ambiente", "areas2": ["arte", "sociedad"], "titulo": "Diseña una campaña de acción ambiental", "resumen": "Diseña una campaña con un objetivo claro, un público concreto, mensajes probados y una forma de medir si logró algo, sobre un tema ambiental que te importe.", "tipo": "Plan", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Campaña", "Comunicación"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Comunicaciones", "Publicidad", "Diseño Gráfico", "Ingeniería Ambiental", "Psicología", "Educación", "Sociología", "Administración"], "problema": ["Muchas campañas ambientales se parecen entre sí: afiches con la tierra, frases generales y poco que hacer. Pasan sin dejar huella porque no hablan a nadie en particular ni piden una acción concreta.", "Una campaña efectiva parte de un público, entiende qué le importa y propone una acción pequeña y posible."], "desarrollar": ["Elige un tema ambiental y un público concreto, como estudiantes de primer ciclo o comerciantes de un mercado, y define qué acción pequeña quieres que realicen.", "Escribe tres mensajes distintos, diseña una pieza para cada uno, pide a unas personas que ordenen cuál entienden y recuerdan más, y arma el plan final con canales, calendario y cómo medirías el resultado."], "ampliaciones": [{"titulo": "Un video corto", "aporta": "convierte el mensaje que mejor funcionó en un video de un minuto."}, {"titulo": "Presupuesto", "aporta": "estima cuánto costaría llevar la campaña a un grupo real."}, {"titulo": "Medir el cambio", "aporta": "diseña una pregunta antes y después para saber si algo cambió."}], "objetivos": ["Elegir un público y una acción concretos.", "Escribir y comparar mensajes.", "Probarlos con personas.", "Planificar la campaña completa."], "habilidades": ["Comunicación persuasiva.", "Diseño gráfico básico.", "Pruebas con usuarios.", "Planificación de campañas."], "herramientas": ["Un editor de diseño o de presentaciones.", "Un formulario anónimo.", "Hoja de cálculo."], "lineamientos": ["Evita mensajes que culpen, asusten con datos dudosos o exageren: usa cifras verificables y cita su fuente.", "Si pruebas la campaña con personas, hazlo con su consentimiento y sin recoger datos personales."], "otroSector": "La misma estructura sirve para campañas de salud, de seguridad, de ahorro o de participación ciudadana."}$a40sld$::jsonb,48),
('cuanta-comida-se-desperdicia-en-tu-casa-o-comedor-y-a-donde-va','ambiente',array['agricultura','sociedad']::text[],'¿Cuánta comida se desperdicia en tu casa o comedor y a dónde va?','Mide durante una semana qué comida se tira en tu casa o en un comedor, por qué ocurre y qué parte se habría podido aprovechar.','Análisis','~15 h',15,array['Alimentos','Residuos']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental ingenieria agroindustrial nutricion estadistica economia administracion educacion ingenieria industrial medicion y registro. analisis de causas. calculo de costos. comunicacion de resultados. balanza de cocina. hoja de calculo. cuaderno de registro.',$a41sld${"id": "cuanta-comida-se-desperdicia-en-tu-casa-o-comedor-y-a-donde-va", "area": "ambiente", "areas2": ["agricultura", "sociedad"], "titulo": "¿Cuánta comida se desperdicia en tu casa o comedor y a dónde va?", "resumen": "Mide durante una semana qué comida se tira en tu casa o en un comedor, por qué ocurre y qué parte se habría podido aprovechar.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Alimentos", "Residuos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Agroindustrial", "Nutrición", "Estadística", "Economía", "Administración", "Educación", "Ingeniería Industrial"], "problema": ["Una parte importante de los alimentos que se compran no llega a comerse: se echan a perder, se cocina de más o se sirve más de lo que alguien termina. Cuando se tira, también se pierden el dinero, el agua y el esfuerzo que costó producirlos.", "Casi nadie lo mide, así que parece un problema menor. Registrar qué se tira y por qué permite encontrar dónde se pierde más."], "desarrollar": ["Durante una semana anota cada alimento que se desecha, el motivo, como se echó a perder, sobró o no gustó, y estima su cantidad con una balanza o por porciones, sin identificar a quién lo dejó.", "Clasifica los motivos, calcula el costo aproximado de lo desechado y propón tres cambios concretos, como planificar compras, guardar mejor o aprovechar sobras."], "ampliaciones": [{"titulo": "Receta de aprovechamiento", "aporta": "inventa tres recetas con lo que más se tira."}, {"titulo": "Costo anual", "aporta": "proyecta cuánto dinero se pierde en un año."}, {"titulo": "Comedor o kiosco", "aporta": "adapta el estudio a un espacio compartido, con permiso."}], "objetivos": ["Medir y registrar el desperdicio.", "Reconocer sus causas.", "Calcular costos aproximados.", "Proponer cambios viables."], "habilidades": ["Medición y registro.", "Análisis de causas.", "Cálculo de costos.", "Comunicación de resultados."], "herramientas": ["Balanza de cocina.", "Hoja de cálculo.", "Cuaderno de registro."], "lineamientos": ["Por higiene, no manipules ni revises comida en mal estado; clasifícala sin tocarla y lávate las manos.", "Registra alimentos y cantidades, no a las personas que los dejaron; los resultados no deben usarse para culpar."], "otroSector": "El mismo análisis sirve para medir desperdicio en un restaurante, un mercado, un colegio o una cadena de suministro."}$a41sld$::jsonb,49),
('se-puede-convertir-tu-basura-organica-en-abono','ambiente',array['agricultura','ciencias']::text[],'¿Se puede convertir tu basura orgánica en abono?','Averigua cuánta basura orgánica produce un hogar y diseña, y si puedes prueba, un sistema simple de compostaje que funcione en un espacio pequeño.','Prototipo','1 mes',30,array['Compostaje','Residuos orgánicos']::text[],array['crear','resolver']::text[],'propios',NULL,'ingenieria ambiental biologia ingenieria agroindustrial quimica ingenieria forestal educacion arquitectura ingenieria industrial diseno de procesos simples. observacion y registro. resolucion de problemas. documentacion. recipientes y materiales reutilizados. termometro y cuaderno de registro. hoja de calculo.',$a42sld${"id": "se-puede-convertir-tu-basura-organica-en-abono", "area": "ambiente", "areas2": ["agricultura", "ciencias"], "titulo": "¿Se puede convertir tu basura orgánica en abono?", "resumen": "Averigua cuánta basura orgánica produce un hogar y diseña, y si puedes prueba, un sistema simple de compostaje que funcione en un espacio pequeño.", "tipo": "Prototipo", "tiempo": "1 mes", "horas": 30, "etiquetas": ["Compostaje", "Residuos orgánicos"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Biología", "Ingeniería Agroindustrial", "Química", "Ingeniería Forestal", "Educación", "Arquitectura", "Ingeniería Industrial"], "problema": ["Gran parte de la basura de una casa es orgánica: cáscaras, restos de comida y hojas. Al mezclarse con lo demás, se pudre sin aprovecharse y genera mal olor y líquidos que complican la recolección.", "El compostaje transforma esos restos en abono, pero se evita por miedo a los olores, las plagas o la falta de espacio. Se puede hacer bien con pocas reglas y un diseño adecuado."], "desarrollar": ["Mide durante una semana cuánto residuo orgánico produce tu hogar y, con fuentes confiables, diseña un sistema de compostaje adaptado a tu espacio, como una compostera cerrada o un tarro con capas, con lista de materiales y reglas de qué sí y qué no echar.", "Si decides probarlo, registra durante cuatro semanas temperatura, olor, humedad y aspecto, y presenta qué funcionó y qué corregirías."], "ampliaciones": [{"titulo": "Medir el resultado", "aporta": "pesa cuánto abono obtienes y cuánto residuo evitaste desechar."}, {"titulo": "Usar el abono", "aporta": "prueba el abono en una planta y compáralo con otra sin abono."}, {"titulo": "Versión comunitaria", "aporta": "diseña cómo funcionaría un compostaje en un edificio, un colegio o un mercado."}], "objetivos": ["Medir el residuo orgánico.", "Diseñar un sistema adecuado al espacio.", "Registrar el proceso con orden.", "Evaluar resultados con honestidad."], "habilidades": ["Diseño de procesos simples.", "Observación y registro.", "Resolución de problemas.", "Documentación."], "herramientas": ["Recipientes y materiales reutilizados.", "Termómetro y cuaderno de registro.", "Hoja de cálculo."], "lineamientos": ["No incluyas carne, lácteos, aceites ni excrementos de mascotas, que atraen plagas y pueden ser riesgosos; lávate las manos y usa guantes al manipular.", "Si hay mal olor persistente o plagas, detén la prueba y consulta fuentes confiables; no la hagas donde moleste a otras personas."], "otroSector": "El mismo enfoque de transformar un residuo en recurso sirve para otros procesos, como aprovechar el calor, el agua o los subproductos de un taller."}$a42sld$::jsonb,50),
('cuanta-energia-solar-podria-aprovechar-un-techo','ambiente',array['industria','ciudades']::text[],'¿Cuánta energía solar podría aprovechar un techo?','Estima con datos públicos de radiación cuánta electricidad podría generar un techo con paneles solares, cuánto costaría y en cuánto tiempo se recuperaría la inversión.','Análisis','~22 h',22,array['Energía solar','Datos']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria electrica ingenieria mecanica fisica arquitectura ingenieria ambiental economia estadistica ingenieria electronica calculo energetico. busqueda de datos publicos. evaluacion economica basica. comunicacion de resultados. datos publicos de radiacion solar. hoja de calculo. una imagen satelital para estimar el techo.',$a43sld${"id": "cuanta-energia-solar-podria-aprovechar-un-techo", "area": "ambiente", "areas2": ["industria", "ciudades"], "titulo": "¿Cuánta energía solar podría aprovechar un techo?", "resumen": "Estima con datos públicos de radiación cuánta electricidad podría generar un techo con paneles solares, cuánto costaría y en cuánto tiempo se recuperaría la inversión.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Energía solar", "Datos"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Eléctrica", "Ingeniería Mecánica", "Física", "Arquitectura", "Ingeniería Ambiental", "Economía", "Estadística", "Ingeniería Electrónica"], "problema": ["Se habla de paneles solares como si fueran la solución para todos, pero la decisión depende del tamaño del techo, de la sombra, de la radiación de la zona y del consumo de la vivienda. Muy pocas personas hacen esas cuentas antes de decidir.", "Sin cálculo, es fácil esperar demasiado o dudar de algo que sí convendría. Un análisis ordenado permite decidir con datos."], "desarrollar": ["Elige un techo, real o ficticio, estima su área útil y busca en datos públicos de un servicio meteorológico o de energía la radiación solar de la zona. Calcula la energía anual que podría producir con supuestos razonables y explícalos.", "Compara con el consumo de un hogar típico, estima el costo aproximado de la instalación con precios que puedas citar y calcula en cuánto tiempo se recuperaría la inversión, indicando la incertidumbre."], "ampliaciones": [{"titulo": "Comparar zonas", "aporta": "calcula lo mismo para tres ciudades con distinta radiación."}, {"titulo": "Sombras", "aporta": "considera cómo cambiarían los resultados con árboles o edificios cercanos."}, {"titulo": "Otros usos", "aporta": "compara la generación con un calentador solar de agua."}], "objetivos": ["Buscar datos de radiación confiables.", "Estimar la generación con supuestos claros.", "Calcular costos y retorno.", "Comunicar los resultados con sus límites."], "habilidades": ["Cálculo energético.", "Búsqueda de datos públicos.", "Evaluación económica básica.", "Comunicación de resultados."], "herramientas": ["Datos públicos de radiación solar.", "Hoja de cálculo.", "Una imagen satelital para estimar el techo."], "lineamientos": ["Cita las fuentes de radiación y de precios, y aclara que los resultados son estimaciones y no un diseño de ingeniería.", "No subas a techos ni manipules instalaciones eléctricas: el análisis se hace con datos y cálculos."], "otroSector": "El mismo cálculo de potencial sirve para estimar el viento, el agua o la biomasa, o el retorno de cualquier inversión en equipos."}$a43sld$::jsonb,51),
('cual-es-la-huella-de-carbono-de-tu-facultad','ambiente',array['negocios','ciudades']::text[],'¿Cuál es la huella de carbono de tu facultad?','Calcula de forma aproximada las emisiones de un espacio educativo, considerando energía, traslados, residuos y papel, y descubre dónde se concentra la mayor parte.','Análisis','1 a 2 meses',35,array['Huella de carbono','Instituciones']::text[],array['investigar','resolver','otro-sector']::text[],'propios',NULL,'ingenieria ambiental ingenieria industrial administracion contabilidad economia estadistica ingenieria de sistemas ingenieria electrica inventario de emisiones. recoleccion de datos. analisis y priorizacion. comunicacion de resultados. factores de emision publicados. hoja de calculo. un formulario anonimo para encuestas breves.',$a44sld${"id": "cual-es-la-huella-de-carbono-de-tu-facultad", "area": "ambiente", "areas2": ["negocios", "ciudades"], "titulo": "¿Cuál es la huella de carbono de tu facultad?", "resumen": "Calcula de forma aproximada las emisiones de un espacio educativo, considerando energía, traslados, residuos y papel, y descubre dónde se concentra la mayor parte.", "tipo": "Análisis", "tiempo": "1 a 2 meses", "horas": 35, "etiquetas": ["Huella de carbono", "Instituciones"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Industrial", "Administración", "Contabilidad", "Economía", "Estadística", "Ingeniería de Sistemas", "Ingeniería Eléctrica"], "problema": ["Las instituciones suelen hablar de sostenibilidad sin saber cuánto emiten realmente. La huella de una facultad incluye lo visible, como la luz, y lo que casi no se mira, como cómo llegan las personas o cuánto papel se usa.", "Sin un inventario, no se puede decidir qué mejorar primero. Hacerlo por primera vez ya es un aporte, aunque sea aproximado."], "desarrollar": ["Define los límites de tu estudio, como una facultad o un edificio, y reúne datos aproximados de energía eléctrica, papel, residuos y traslados de estudiantes, usando datos publicados, observaciones o encuestas anónimas, y anota qué dato es estimado.", "Calcula las emisiones con factores públicos, muestra qué categorías pesan más y propón tres acciones prioritarias con un efecto estimado."], "ampliaciones": [{"titulo": "Ver la evolución", "aporta": "propón cómo se actualizaría el inventario cada año."}, {"titulo": "Compartir los resultados", "aporta": "convierte el inventario en un informe para presentarlo a autoridades."}, {"titulo": "Comparar con otra", "aporta": "compara tus resultados con los de otra facultad o institución."}], "objetivos": ["Definir límites y categorías del inventario.", "Reunir datos y documentar supuestos.", "Calcular emisiones.", "Priorizar acciones."], "habilidades": ["Inventario de emisiones.", "Recolección de datos.", "Análisis y priorización.", "Comunicación de resultados."], "herramientas": ["Factores de emisión publicados.", "Hoja de cálculo.", "Un formulario anónimo para encuestas breves."], "lineamientos": ["Pide autorización antes de recoger datos en una institución real y no registres información personal en las encuestas.", "Presenta los resultados como una primera aproximación y no como una medición oficial."], "otroSector": "El mismo inventario sirve para estimar la huella de un evento, una empresa, un colegio o un restaurante."}$a44sld$::jsonb,52),
('como-suena-tu-entorno-mapa-de-ruido','ambiente',array['salud','ciudades']::text[],'¿Cómo suena tu entorno? Mapa de ruido','Mide con una aplicación el nivel de ruido en distintos puntos de tu entorno y a distintas horas para descubrir dónde y cuándo hay más ruido y qué lo causa.','Análisis','~20 h',20,array['Ruido','Mapas']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental fisica ingenieria civil arquitectura ingenieria electronica estadistica psicologia geografia medicion y registro. analisis espacial basico. interpretacion de datos. comunicacion de resultados. una aplicacion de sonometro. hoja de calculo. un mapa digital.',$a45sld${"id": "como-suena-tu-entorno-mapa-de-ruido", "area": "ambiente", "areas2": ["salud", "ciudades"], "titulo": "¿Cómo suena tu entorno? Mapa de ruido", "resumen": "Mide con una aplicación el nivel de ruido en distintos puntos de tu entorno y a distintas horas para descubrir dónde y cuándo hay más ruido y qué lo causa.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Ruido", "Mapas"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Física", "Ingeniería Civil", "Arquitectura", "Ingeniería Electrónica", "Estadística", "Psicología", "Geografía"], "problema": ["El ruido es una forma de contaminación que se normaliza: tráfico, construcciones, bocinas o locales. No deja residuos visibles, pero afecta el descanso, la concentración y el bienestar de quienes viven o estudian cerca.", "Casi nunca se mide, y sin datos es difícil mostrar que un lugar es especialmente ruidoso o decidir dónde conviene intervenir."], "desarrollar": ["Elige diez puntos de un espacio como tu barrio o tu campus y mide el nivel de sonido en cada uno con una aplicación de sonómetro en tres horarios distintos, siempre con el mismo método y durante el mismo tiempo.", "Presenta un mapa con colores, compara con valores de referencia de organismos oficiales y explica qué fuentes parecen ser las responsables, indicando las limitaciones de tu medición."], "ampliaciones": [{"titulo": "Comparar días", "aporta": "compara un día de semana con un fin de semana."}, {"titulo": "Zonas de silencio", "aporta": "identifica lugares tranquilos que podrían protegerse."}, {"titulo": "Efecto de barreras", "aporta": "compara cuánto baja el ruido con un muro o con árboles."}], "objetivos": ["Diseñar un plan de medición comparable.", "Registrar y organizar los datos.", "Representarlos en un mapa.", "Interpretar las diferencias con cautela."], "habilidades": ["Medición y registro.", "Análisis espacial básico.", "Interpretación de datos.", "Comunicación de resultados."], "herramientas": ["Una aplicación de sonómetro.", "Hoja de cálculo.", "Un mapa digital."], "lineamientos": ["Aclara que las aplicaciones de celular dan valores aproximados y no sustituyen a un sonómetro profesional; no los uses como prueba legal.", "Cuida tu seguridad al medir cerca de calles y no registres conversaciones ni grabes a personas."], "otroSector": "El mismo método de mapeo sirve para temperatura, luz, olores, calidad de la señal de internet o aglomeración."}$a45sld$::jsonb,53)
